PRAGMA foreign_key_check;

-- Gold Query
SELECT A FROM (SELECT AVG(finishing) AS result, 'Max' AS A FROM Player AS T1 INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id WHERE T1.height = (SELECT MAX(height) FROM Player) UNION SELECT AVG(finishing) AS result, 'Min' AS A FROM Player AS T1 INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id WHERE T1.height = (SELECT MIN(height) FROM Player)) ORDER BY result DESC, A NULLS LAST LIMIT 1;

/*
Gold Result:
('Max',)
*/

-- Prediction Query
SELECT T1.player_name FROM Player AS T1 INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id WHERE T1.height >= (SELECT MIN(height) FROM Player WHERE height > 0) AND T1.height <= (SELECT MAX(height) FROM Player) GROUP BY T1.id ORDER BY AVG(T2.finishing) DESC, T1.player_name NULLS LAST LIMIT 1;

/*
Prediction Result:
('Tyler Rogers',)
*/